def payout_risk_scale(payouts):
    pay = [float(x) for x in payouts]
    if len(pay) < 2:
        return 1.0
    lo = min(pay)
    rel = [x - lo for x in pay]
    tot = sum(rel)
    if tot <= 0:
        return 1.0
    flat = 1.0 - max(rel) / tot
    return max(0.0, min(1.0, flat / 0.5))
