        self.o3_seen = [0] * rules.num_players
        self.o3_fold = [0] * rules.num_players
        self.aggressor = None
        self.dealt = [0] * rules.num_players
        self.pf_faced = [0] * rules.num_players
        self.pf_fold = [0] * rules.num_players
        self.pre_raises = [0] * rules.num_players
